// (That second line just silences native-AOT trimming warnings that
// file-based web apps emit for reflection-based JSON — ignore it.)
//
// 34 — pagination & filtering (ORIGINAL, flawed on purpose)
//
// A product catalogue with 10,000 items and an API that hands you all of them,
// every time, and then apologises in the comments.
//
// Run:   dotnet run csharp/34-pagination-filtering/original.cs
// Try:
//   curl -s http://localhost:5034/products | wc -c        (or just watch the
//        server console — it prints the payload size for every request)
//
//   THE OFF-BY-ONE, in two commands:
//   curl "http://localhost:5034/products/page?page=0"     -> products 1..20
//   curl "http://localhost:5034/products/page?page=1"     -> products 21..40
//        Page ONE is the SECOND page. Every client that says "page 1" for the
//        first page silently skips twenty products, and nobody notices until
//        a customer asks why they can't find "Rustic Chair #00003".
//
//   THE CRASHES, one command each:
//   curl -i "http://localhost:5034/products/page?page=-1"   -> 500
//   curl -i "http://localhost:5034/products/page?page=abc"  -> 500
//   curl -i "http://localhost:5034/products/page?page=9999" -> 500
//   curl -i "http://localhost:5034/products/sorted?sort=pirce" -> 500
//        Four different ways for a client to take the server down with a
//        query string. None of them are the client's fault.

using System.Text.Json;

var app = WebApplication.CreateBuilder(args).Build();

var categories = new[] { "tools", "toys", "books", "food", "garden" };
var adjectives = new[] { "Rustic", "Sleek", "Handmade", "Refined", "Ergonomic" };
var nouns = new[] { "Chair", "Lamp", "Table", "Mug", "Shelf" };

var products = new List<Product>();
for (int i = 1; i <= 10_000; i++)
    products.Add(new Product(
        i,
        $"{adjectives[i % 5]} {nouns[(i / 5) % 5]} #{i:D5}",
        categories[i % 5],
        1.99m + (i % 500),
        i % 97));

// ---------------------------------------------------------------------------
// FLAW #1: the whole table, on every request.
// ---------------------------------------------------------------------------
app.MapGet("/products", () =>
{
    var json = JsonSerializer.Serialize(products);

    // Watch this number in the console. It is the same number for a phone on
    // a train as for a datacentre — the server has no idea and no opinion.
    Console.WriteLine($"[/products] serialized {json.Length:N0} bytes for ONE request");

    // The team's official position, recorded here for posterity:
    //
    //   "It's fine, the frontend filters it. Just do
    //        products.filter(p => p.name.includes(q))
    //    in the browser and only render 20 of them."
    //
    // Which means: the database read 10,000 rows, the server serialized ~1MB
    // of JSON, the network carried all of it, the phone parsed all of it and
    // built 10,000 objects in memory — so that JavaScript could throw away
    // 9,980 of them. Every keystroke in the search box. The user sees a
    // spinner and blames their connection.
    return Results.Text(json, "application/json");
});

// ---------------------------------------------------------------------------
// FLAW #2: someone added paging. Sort of.
// ---------------------------------------------------------------------------
app.MapGet("/products/page", (HttpContext ctx) =>
{
    // Hand-rolled query parsing. int.Parse throws FormatException on anything
    // that isn't a number — "abc", "1.5", "٣", an empty retry from a flaky
    // client — and an unhandled exception in an endpoint is a 500. The client
    // sent bad input; the SERVER reports that it is broken.
    var raw = ctx.Request.Query["page"].ToString();
    var page = raw.Length == 0 ? 0 : int.Parse(raw);

    // The off-by-one, in one expression: page 0 is the first page. Every REST
    // API in the world starts at page 1, so every client here is off by
    // exactly twenty products, forever.
    var start = page * 20;

    // GetRange throws ArgumentOutOfRangeException when start is negative
    // (?page=-1) and when start is past the end (?page=9999). Two more 500s
    // reachable from the address bar.
    var slice = products.GetRange(start, Math.Min(20, products.Count - start));

    // And notice what's missing from the response: how many products exist,
    // how many pages there are, whether this is the last one. The client gets
    // twenty objects and has to guess. "Is there a next page?" is answered by
    // requesting it and seeing whether the server crashes.
    return Results.Ok(slice);
});

// ---------------------------------------------------------------------------
// FLAW #3: sorting by whatever the client types.
// ---------------------------------------------------------------------------
app.MapGet("/products/sorted", (string sort) =>
{
    // Reflection driven by a query string. Two problems, both bad:
    //   1. An unknown name gives null -> NullReferenceException -> 500.
    //      "?sort=pirce" is a typo; the response is a stack trace.
    //   2. Every property name on Product is now part of your public API. Add
    //      an internal CostPrice or SupplierMargin property one day and it is
    //      instantly sortable — and therefore *guessable* — by strangers.
    var prop = typeof(Product).GetProperty(sort);
    return Results.Ok(products.OrderBy(p => prop!.GetValue(p)).Take(20));
});

app.Run("http://localhost:5034");

record Product(int Id, string Name, string Category, decimal Price, int Stock);

# 🏋️ Practice: Pagination & Filtering

Do these after reading LEARN.md and the README. Solutions are at the bottom — try each exercise before peeking.

## Exercises

### ⭐ 1. Tell the client where it is (warm-up)

The envelope has the numbers, but every client now writes the same two lines to work out whether the
Next button should be enabled. Add `HasNext` and `HasPrevious` as computed properties on
`PagedResult<T>` — no new constructor parameters, no changes to `Paginator.Slice`. They serialize into
the JSON automatically.
*Practices:* derived state on a record, and moving a calculation every caller repeats into the one
place that owns the data.
**Hint:** `HasNext => Page < TotalPages;` and `HasPrevious => Page > 1 && TotalPages > 0;`. Sanity-check
both against the empty result (zero pages) before you write them — that is the case that makes the
naive version wrong.
**Check offline:** add to `Tests.cs`:
```csharp
var first = Paginator.Slice(Enumerable.Range(1, 25).ToList(), new PageRequest(1, 10, "id", null));
Check.Equal(false, first.HasPrevious, "page 1 has no previous");
Check.Equal(true, first.HasNext, "page 1 of 3 has a next");
var last = Paginator.Slice(Enumerable.Range(1, 25).ToList(), new PageRequest(3, 10, "id", null));
Check.Equal(true, last.HasPrevious, "the last page has a previous");
Check.Equal(false, last.HasNext, "the last page has no next");
var none = Paginator.Slice(new List<int>(), new PageRequest(1, 10, "id", null));
Check.Equal(false, none.HasNext, "an empty result has no next");
Check.Equal(false, none.HasPrevious, "...and no previous either");
```
Then `curl "http://localhost:5034/products?page=500"` and look for `"hasNext":false`.

### ⭐⭐ 2. Price range, and a rule that needs two fields (core)

Add `?minPrice=` and `?maxPrice=` (both `decimal?`). A negative minimum **clamps** to 0 — obvious
intent. But `minPrice=10&maxPrice=5` is a **rejection**: it is not obviously a typo in either field,
and quietly returning nothing would look identical to "no products match", which is a different fact.
Add both parameters to `PageRequest` *with defaults* so existing calls still compile.
*Practices:* a validation rule that spans two fields, and the clamp/reject decision made twice in one
feature.
**Hint:** positional records accept defaults — `public record PageRequest(..., decimal? MinPrice = null, decimal? MaxPrice = null)`
— so every `new PageRequest(1, 10, "id", null)` in `Tests.cs` keeps working. `Validate` needs the two
new arguments, and should still return *all* problems at once.
**Check offline:** add to `Tests.cs`:
```csharp
Check.Equal(0, PageRequest.Validate(null, 5m, 10m).Count, "min below max is valid");
Check.Equal(0, PageRequest.Validate(null, 10m, 10m).Count, "min equal to max is valid");
Check.Equal(1, PageRequest.Validate(null, 10m, 5m).Count, "min above max is rejected");
Check.True(PageRequest.Validate(null, 10m, 5m)[0].Contains("minPrice"), "the error names the parameter");
Check.Equal(2, PageRequest.Validate("pirce", 10m, 5m).Count, "both problems are reported at once");
Check.Equal(0m, PageRequest.Normalize(null, null, null, null, -5m, null).MinPrice, "a negative minPrice clamps to 0");

var catalog = Small();
var ranged = ProductQuery.Apply(catalog.Products, PageRequest.Normalize(1, 10, "id", null, 5m, 10m));
Check.Equal(3, ranged.TotalItems, "3 products cost between 5 and 10 inclusive");
Check.Equal(2, ProductQuery.Apply(catalog.Products, PageRequest.Normalize(1, 10, "id", "rustic", 5m, 10m)).TotalItems,
    "search and price range compose");
```
Then `curl -i "http://localhost:5034/products?minPrice=10&maxPrice=5"` → `400`.

### ⭐⭐ 3. A facet is not a search (core)

Add `?category=tools` — an **exact**, case-insensitive match, separate from `search`. Note the contrast
with exercise 2: an unknown category gets an empty page, *not* a 400, because "show me products in a
category with no products" is a perfectly clear request with a correct empty answer. Then add
`GET /products/categories` returning each category with its product count, so a client can build the
filter UI without guessing.
*Practices:* distinguishing a fuzzy search from an exact facet, and noticing that "reject the
ambiguous" does not mean "reject the unfamiliar".
**Hint:** `string.Equals(p.Category, request.Category, StringComparison.OrdinalIgnoreCase)` — `Equals`,
not `Contains`, is the whole difference. Refactoring `Filter` to take the whole `PageRequest` instead
of just the search string keeps its signature from growing a parameter per filter.
**Check offline:** add to `Tests.cs`:
```csharp
var c = Small().Products;
Check.Equal(2, ProductQuery.Apply(c, PageRequest.Normalize(1, 10, "id", null, null, null, "tools")).TotalItems,
    "category is an exact filter");
Check.Equal(2, ProductQuery.Apply(c, PageRequest.Normalize(1, 10, "id", null, null, null, "TOOLS")).TotalItems,
    "...case-insensitively");
Check.Equal(0, ProductQuery.Apply(c, PageRequest.Normalize(1, 10, "id", null, null, null, "tool")).TotalItems,
    "a PREFIX is not a category — exact, unlike search");
Check.Equal(0, ProductQuery.Apply(c, PageRequest.Normalize(1, 10, "id", null, null, null, "nope")).TotalItems,
    "an unknown category is an empty page, not a 400");

var facets = ProductQuery.Categories(c);
Check.Equal(4, facets.Count, "four distinct categories");
Check.Equal("books", facets[0].Name, "facets come back alphabetical");
Check.Equal(2, facets.First(f => f.Name == "tools").Count, "and carry their counts");
```

### ⭐⭐ 4. Prove the pages tile (core)

Add `"category"` to the sort whitelist and to `ProductQuery.Sort`. It has only five distinct values, so
in a 500-product catalogue almost every item is tied with 99 others — exactly the situation where a
missing tie-break silently duplicates and drops products. Then write a **property test**: for several
page sizes, walk every page and assert that each product appeared exactly once.
*Practices:* testing a property of the whole result ("the pages tile") instead of one example, which is
how you catch the bugs you did not think of.
**Hint:** loop `foreach (var size in new[] { 1, 7, 100, 499, 500, 501 })` — the interesting sizes are 1,
a size that divides unevenly, one below the total, exactly the total, and one above it. Collect every
page's ids into a list and compare `seen.Count` against `seen.Distinct().Count()`; if they differ, some
product came back twice and another never came at all.
**Check offline:** add to `Tests.cs`:
```csharp
Check.Equal(0, PageRequest.Validate("category", null, null).Count, "category is a whitelisted sort field now");
Check.Equal("4,5,1,3,2", Ids(ProductQuery.Sort(Small().Products, "category")), "category ascending, ties by id");
Check.Equal("2,3,1,5,4", Ids(ProductQuery.Sort(Small().Products, "-category")), "descending reverses the ties too");

var many = ProductCatalog.Seeded(500).Products;
foreach (var size in new[] { 1, 7, 100, 499, 500, 501 })
{
    var seen = new List<int>();
    var pages = ProductQuery.Apply(many, PageRequest.Normalize(1, size, "category", null)).TotalPages;
    for (int p = 1; p <= pages; p++)
        seen.AddRange(ProductQuery.Apply(many, PageRequest.Normalize(p, size, "category", null)).Items.Select(x => x.Id));
    Check.Equal(500, seen.Count, $"pageSize {size}: every product appears...");
    Check.Equal(500, seen.Distinct().Count(), $"pageSize {size}: ...exactly once");
}
```
Then delete the `ThenBy`/`ThenByDescending` and run it again to see what the property test is *for*.

### ⭐⭐⭐ 5. Pagination that survives a delete (challenge)

Offset pagination has a flaw no amount of clamping fixes: it is defined relative to a *position*, and
positions move. Delete one product between a client's page 1 and page 2 and everything shifts up by
one — so the product that was first on page 2 is now last on page 1, and the client never sees it.
Implement **keyset (cursor) pagination**: `Paginator.After(byId, after, pageSize)` returning
`CursorPage<Product>(Items, NextCursor, PageSize)`, where the cursor is the last id on the page. Expose
it as `GET /products/feed?after=&limit=`.
*Practices:* choosing a pagination strategy from its failure modes, and the peek-one-ahead trick.
**Hint:** `Where(p => after is null || p.Id > after.Value).Take(pageSize + 1)` — taking **one extra**
item is how you learn whether a next page exists without a second query. If you got `pageSize + 1`
back, drop the extra and return a cursor; if you got fewer, the cursor is `null` and the feed is done.
The list must be ordered by the cursor column, which is why the parameter is named `byId`.
**Check offline:** add to `Tests.cs`:
```csharp
var byId = Small().Products.OrderBy(p => p.Id).ToList();
var k1 = Paginator.After(byId, null, 2);
Check.Equal("1,2", Ids(k1.Items), "the first cursor page starts at the beginning");
Check.Equal(2, k1.NextCursor, "the cursor is the last id on the page");
var k2 = Paginator.After(byId, k1.NextCursor, 2);
Check.Equal("3,4", Ids(k2.Items), "the next page follows the cursor");
var k3 = Paginator.After(byId, k2.NextCursor, 2);
Check.Equal("5", Ids(k3.Items), "the last page is partial");
Check.Equal(null, k3.NextCursor, "and its cursor is null: there is no more");
Check.Equal(0, Paginator.After(byId, 999, 2).Items.Count, "a cursor past the end gives an empty page");

// The whole point, in five lines: somebody deletes product 1 between page 1 and page 2.
var afterDelete = byId.Where(p => p.Id != 1).ToList();
Check.Equal("4,5", Ids(Paginator.Slice(afterDelete, new PageRequest(2, 2, "id", null)).Items),
    "OFFSET page 2 skipped product 3 entirely");
Check.Equal("3,4", Ids(Paginator.After(afterDelete, 2, 2).Items),
    "KEYSET page 2 skipped nothing");
```

## Solutions

### 1. Tell the client where it is

```csharp
// Paginator.cs
public record PagedResult<T>(
    IReadOnlyList<T> Items,
    int Page,
    int PageSize,
    int TotalItems,
    int TotalPages)
{
    /// Derived, not stored: there is exactly one source of truth for "where am
    /// I", and these two read it rather than duplicating it.
    public bool HasPrevious => Page > 1 && TotalPages > 0;
    public bool HasNext => Page < TotalPages;
}
```

WHY: a computed property beats two more constructor parameters for the same reason a database has no
"age" column next to "birth date" — stored derived values drift from what they were derived from, and
the compiler cannot notice. `System.Text.Json` serializes public getters, so these appear in the response
without touching `Paginator.Slice` or any endpoint. The `TotalPages > 0` guard on `HasPrevious` is the
part worth pausing on: with zero results there are zero pages, so `page=1` is simultaneously the first
page and past the end. Every "which page am I on" bug lives in the empty case.

### 2. Price range, and a rule that needs two fields

```csharp
// PageRequest.cs — defaults keep every existing construction site compiling
public record PageRequest(int Page, int PageSize, string Sort, string? Search,
                          decimal? MinPrice = null, decimal? MaxPrice = null)
{
    public static IReadOnlyList<string> Validate(string? sort, decimal? minPrice, decimal? maxPrice)
    {
        var errors = new List<string>();

        if (!string.IsNullOrWhiteSpace(sort))
        {
            var (field, _) = ParseSort(sort.Trim().ToLowerInvariant());
            if (!SortFields.Contains(field))
                errors.Add($"unknown sort field '{field}'. Allowed: {string.Join(", ", SortFields)} " +
                           "(prefix with '-' for descending, e.g. -price)");
        }

        // A rule NEITHER field can check alone — which is exactly why validation
        // belongs to the request as a whole, not to each parameter.
        if (minPrice is not null && maxPrice is not null && minPrice > maxPrice)
            errors.Add($"minPrice ({minPrice}) must not be greater than maxPrice ({maxPrice})");

        return errors;
    }

    // Normalize gains two more clamped arguments; the first four are unchanged.
    //     minPrice is null ? null : Math.Max(0m, minPrice.Value),   // negative money is not a thing
    //     maxPrice is null ? null : Math.Max(0m, maxPrice.Value));

// ProductQuery.cs — Filter now takes the whole request
public static IReadOnlyList<Product> Filter(IReadOnlyList<Product> products, PageRequest request)
{
    IEnumerable<Product> rows = products;

    if (!string.IsNullOrWhiteSpace(request.Search))
        rows = rows.Where(p => p.Name.Contains(request.Search, StringComparison.OrdinalIgnoreCase)
                            || p.Category.Contains(request.Search, StringComparison.OrdinalIgnoreCase));

    if (request.MinPrice is not null) rows = rows.Where(p => p.Price >= request.MinPrice.Value);
    if (request.MaxPrice is not null) rows = rows.Where(p => p.Price <= request.MaxPrice.Value);

    return rows.ToList();          // one enumeration, at the end
}

// Program.cs — two more typed parameters, passed into Validate and Normalize.
```

WHY: `minPrice > maxPrice` is a rule neither field can enforce alone, and that is the argument for
validating the *request object* rather than sprinkling checks per parameter — a habit that scales to
"end date after start date", "discount not above total", and every other pairwise rule. Why reject
rather than helpfully swap them? Because a swap answers a question the client did not ask, and the two
readings ("fields typed backwards" vs "their code computed a bad range") call for opposite responses.
Returning zero results would be worse: indistinguishable from a genuine empty range, so the client's bug
hides as data. The negative-minimum clamp *is* unambiguous — there is no price below zero — so nothing
is lost by fixing that one silently.

Note the defaults on the record parameters: two new positional members would normally break every
`new PageRequest(...)` in the test suite, and `= null` keeps them all compiling (cs#21's `CreatedAt`
trick).

### 3. A facet is not a search

```csharp
// PageRequest.cs — one more optional member
public record PageRequest(int Page, int PageSize, string Sort, string? Search,
                          decimal? MinPrice = null, decimal? MaxPrice = null, string? Category = null);

// ...in Normalize, alongside the others:
    string.IsNullOrWhiteSpace(category) ? null : category.Trim()

// ProductQuery.cs
public record Facet(string Name, int Count);

// ...in Filter, after the search clause:
if (request.Category is not null)
    rows = rows.Where(p => string.Equals(p.Category, request.Category, StringComparison.OrdinalIgnoreCase));

public static IReadOnlyList<Facet> Categories(IReadOnlyList<Product> products)
    => products.GroupBy(p => p.Category)
               .Select(g => new Facet(g.Key, g.Count()))
               .OrderBy(f => f.Name, StringComparer.Ordinal)
               .ToList();

// Program.cs
app.MapGet("/products/categories", (ProductCatalog catalog) =>
    Results.Ok(ProductQuery.Categories(catalog.Products)));
```

WHY: `search` and `category` look like the same feature and are not. Search is a guess the user is
making — fuzzy, substring, forgiving — so `"cha"` finding "Rustic Chair" is desired. A facet is a choice
the user made from a list *you gave them*, so `"tool"` matching `"tools"` would be a bug: the filter no
longer corresponds to the button they clicked. `Equals` versus `Contains` is the entire difference, and
getting it backwards produces a filter that is subtly, occasionally wrong.

`/products/categories` exists because a facet filter is useless without the list of facets — otherwise
the client hard-codes five strings that drift from your data the day someone adds a category. The counts
are nearly free (`GroupBy` already knows them) and let the UI grey out empty options.

And an unknown category returns an empty page rather than a 400, which looks like it contradicts LEARN's
"reject the ambiguous" rule but doesn't: `?category=nope` is not ambiguous. It clearly means "products in
category nope", and "there are none" is the correct answer. The rule is about *ambiguity*, not
unfamiliarity — `?sort=pirce` gets a 400 because there is no correct answer to give.

### 4. Prove the pages tile

```csharp
// PageRequest.cs
public static readonly IReadOnlyList<string> SortFields = ["id", "name", "price", "stock", "category"];

// ProductQuery.cs — two more branches in the whitelist switch
("category", false) => products.OrderBy(p => p.Category, StringComparer.Ordinal),
("category", true)  => products.OrderByDescending(p => p.Category, StringComparer.Ordinal),
```

The test is the exercise:

```csharp
// Tests.cs
var many = ProductCatalog.Seeded(500).Products;
foreach (var size in new[] { 1, 7, 100, 499, 500, 501 })
{
    var seen = new List<int>();
    var pages = ProductQuery.Apply(many, PageRequest.Normalize(1, size, "category", null)).TotalPages;
    for (int p = 1; p <= pages; p++)
        seen.AddRange(ProductQuery.Apply(many, PageRequest.Normalize(p, size, "category", null))
            .Items.Select(x => x.Id));

    Check.Equal(500, seen.Count, $"pageSize {size}: every product appears...");
    Check.Equal(500, seen.Distinct().Count(), $"pageSize {size}: ...exactly once");
}
```

WHY: the two assertions look redundant and are not. `seen.Count == 500` catches products that were
*dropped*; `seen.Distinct().Count() == 500` catches products that were *duplicated*. An unstable sort
produces both at once — one item slides from page 2 to page 1 and another slides the other way — so a
test checking only one could pass while the result set was scrambled.

This is a **property test**: rather than asserting that a specific page holds specific ids, it asserts an
invariant that must hold for *every* page size and lets the loop find the counterexample. The sizes are
not arbitrary — 1 (every page a boundary), 7 (divides unevenly, partial last page), 100 (divides evenly),
499 / 500 / 501 (one below, exactly, one above the total). Those shapes are where slicing arithmetic
breaks, and enumerating them beats trusting yourself to imagine the failure.

Adding `category` first is what makes the test meaningful: with five distinct values across 500 products,
every page boundary lands inside a hundred-way tie. Sorting by `id` would pass this test with the
tie-break deleted — which is why "my tests are green" and "my code is correct" are different claims.

### 5. Pagination that survives a delete

```csharp
// Paginator.cs
public record CursorPage<T>(IReadOnlyList<T> Items, int? NextCursor, int PageSize);

/// Keyset pagination: "the next N items AFTER this id".
/// `byId` must be ordered by the cursor column — the cursor is a position in
/// that order, not an offset into a list.
public static CursorPage<Product> After(IReadOnlyList<Product> byId, int? after, int pageSize)
{
    // Take ONE MORE than asked. If we get it, there is a next page; if we
    // don't, this is the end. One pass, no second count query.
    var window = byId
        .Where(p => after is null || p.Id > after.Value)
        .Take(pageSize + 1)
        .ToList();

    var hasMore = window.Count > pageSize;
    var items = hasMore ? window.Take(pageSize).ToList() : window;

    return new CursorPage<Product>(items, hasMore ? items[^1].Id : null, pageSize);
}

// Program.cs
app.MapGet("/products/feed", (int? after, int? limit, ProductCatalog catalog) =>
{
    var pageSize = limit is null ? PageRequest.DefaultPageSize : Math.Clamp(limit.Value, 1, PageRequest.MaxPageSize);
    var byId = catalog.Products.OrderBy(p => p.Id).ToList();
    return Results.Ok(Paginator.After(byId, after, pageSize));
});
```

WHY: offset pagination answers "give me items 21 through 40", which is a question about *positions*, and
positions move whenever anything is inserted or deleted. Delete one product while a user reads page 1 and
every later item shifts up a slot: the item that was 21st becomes 20th, the client asks for 21–40, and
that product is never shown to anyone. On an infinite-scroll feed, where insertions happen constantly at
the front, that drift is not an edge case — it is why such feeds show you the same post three times.

Keyset pagination asks about *content* instead: "the next twenty items after the one with id 2". Deleting
id 1 does not change the answer, because the cursor names an item rather than a count. The peek-one-ahead
trick is worth stealing too: the obvious way to answer "is there a next page?" is a second counting
query, an extra round trip per page, whereas fetching `pageSize + 1` answers it inside the query you were
already making, for one row.

The trade: keyset has no page numbers and no "jump to page 47", because it never computes a total. Offset
gives numbered pages and random access; keyset gives correctness under concurrent writes. Catalogue with
a pager → offset. Feed with a Load More button → keyset. Knowing which one your screen actually is beats
reaching for the familiar one.

// Tiny test helper — real projects use xUnit (a NuGet package); this repo
// hand-rolls the same idea so everything runs offline with zero setup.
public static class Check
{
    static int passed, failed;
    public static void Equal<T>(T expected, T actual, string name)
    {
        if (Equals(expected, actual)) { passed++; Console.WriteLine($"  ok  {name}"); }
        else { failed++; Console.WriteLine($"  FAIL {name}\n       expected: {expected}\n       actual:   {actual}"); }
    }
    public static void True(bool condition, string name) => Equal(true, condition, name);
    public static void Throws<TEx>(Action act, string name) where TEx : Exception
    {
        try { act(); failed++; Console.WriteLine($"  FAIL {name} (no exception thrown)"); }
        catch (TEx) { passed++; Console.WriteLine($"  ok  {name}"); }
    }
    public static int Summary()
    {
        Console.WriteLine($"{passed} passed, {failed} failed");
        return failed == 0 ? 0 : 1;
    }
}

// One record that captures everything a list endpoint accepts, plus the two
// pure functions that make it trustworthy.
//
// The governing rule, and it is worth saying out loud before reading the code:
//
//     CLAMP what has an obvious intent. REJECT what doesn't.
//
// `?page=-3` obviously means "the first page" — nobody typed -3 hoping for an
// error message, so clamping to 1 is a kindness with no ambiguity. `?sort=pirce`
// has no obvious intent: we could guess "price", we could ignore it and return
// id order, and both guesses can silently hand the caller the wrong data. So
// that one gets a 400 with the allowed values listed. Guessing is only safe
// when there is exactly one thing the user could have meant.
//
// `?pageSize=100000` is the interesting middle case. The intent is obvious
// ("everything"), but honouring it re-creates the original's problem — so we
// clamp to MaxPageSize. A cap is not a limitation on the caller; it is the
// server refusing to be talked into a denial of service by a query string.

public record PageRequest(int Page, int PageSize, string Sort, string? Search)
{
    public const int DefaultPageSize = 20;
    public const int MaxPageSize = 100;
    public const string DefaultSort = "id";

    /// The whitelist. Anything not on this list is a 400, which means adding an
    /// internal property to `Product` can never accidentally make it sortable
    /// (and therefore discoverable) by a stranger with a query string.
    public static readonly IReadOnlyList<string> SortFields = ["id", "name", "price", "stock"];

    /// "price" -> (price, ascending); "-price" -> (price, descending).
    public static (string Field, bool Descending) ParseSort(string sort)
        => sort.StartsWith('-') ? (sort[1..], true) : (sort, false);

    /// The REJECT half. Returns every problem at once (cs#17's validation
    /// shape) so a client fixing their URL doesn't need three round trips.
    public static IReadOnlyList<string> Validate(string? sort)
    {
        var errors = new List<string>();

        if (!string.IsNullOrWhiteSpace(sort))
        {
            var (field, _) = ParseSort(sort.Trim().ToLowerInvariant());
            if (!SortFields.Contains(field))
                errors.Add($"unknown sort field '{field}'. Allowed: {string.Join(", ", SortFields)} " +
                           "(prefix with '-' for descending, e.g. -price)");
        }

        return errors;
    }

    /// The CLAMP half. Total function: whatever you pass in, a usable
    /// PageRequest comes out. It cannot throw, which is the point — no query
    /// string should ever be able to produce a 500.
    public static PageRequest Normalize(int? page, int? pageSize, string? sort, string? search)
    {
        var normalizedPage = page is null || page < 1 ? 1 : page.Value;

        var normalizedSize = pageSize is null
            ? DefaultPageSize
            : Math.Clamp(pageSize.Value, 1, MaxPageSize);

        var normalizedSort = string.IsNullOrWhiteSpace(sort)
            ? DefaultSort
            : sort.Trim().ToLowerInvariant();

        // Blank search means "no search", not "search for nothing". Collapsing
        // "" and "   " and null into one value here means the query code below
        // has exactly one case to handle instead of four.
        var normalizedSearch = string.IsNullOrWhiteSpace(search) ? null : search.Trim();

        return new PageRequest(normalizedPage, normalizedSize, normalizedSort, normalizedSearch);
    }
}

// The envelope, and the six lines of arithmetic that fill it.
//
// This is generic (`<T>`) because slicing has nothing to do with products.
// Orders, users, log lines — any already-ordered list pages the same way, and
// keeping the arithmetic in one generic place means the off-by-one gets fixed
// once for everything (cs#11's lesson).

public record PagedResult<T>(
    IReadOnlyList<T> Items,
    int Page,
    int PageSize,
    int TotalItems,
    int TotalPages);

public static class Paginator
{
    /// `ordered` must already be filtered and sorted — this method only slices.
    /// Splitting "which items" from "which twenty of them" keeps both testable.
    public static PagedResult<T> Slice<T>(IReadOnlyList<T> ordered, PageRequest request)
    {
        var totalItems = ordered.Count;

        // Ceiling division without floating point: (a + b - 1) / b. Using
        // Math.Ceiling(25 / 10.0) would work too, but doubles in page-count
        // arithmetic is how you end up one page short at exactly one size.
        var totalPages = totalItems == 0
            ? 0
            : (totalItems + request.PageSize - 1) / request.PageSize;

        // PAGE 1 SKIPS NOTHING. This single `- 1` is the entire off-by-one
        // lesson, and the reason it lives here — once, in a tested function —
        // instead of being retyped in every endpoint that lists something.
        //
        // The cast to `long` is not decoration: `(int.MaxValue - 1) * 20`
        // overflows int and wraps NEGATIVE, and `Skip(negative)` skips nothing,
        // so `?page=2000000000` would quietly return page one. Overflow bugs
        // don't announce themselves; they hand you plausible data.
        long skip = (long)(request.Page - 1) * request.PageSize;

        var items = skip >= totalItems
            ? Array.Empty<T>()                       // past the end: empty page, not an error
            : ordered.Skip((int)skip).Take(request.PageSize).ToArray();

        // Note what's in the envelope: the client now knows how many items
        // exist and how many pages there are, so "is there a next page?" is
        // arithmetic instead of an experiment.
        return new PagedResult<T>(items, request.Page, request.PageSize, totalItems, totalPages);
    }
}

// The domain: a product, and a catalogue holding some.
//
// `ProductCatalog` takes its products as a constructor argument rather than
// generating them internally, for the usual reason — tests want a catalogue of
// four items with prices they chose, not 10,000 items they have to reason
// about. `Seeded()` is what the app uses.

public record Product(int Id, string Name, string Category, decimal Price, int Stock);

public class ProductCatalog
{
    public IReadOnlyList<Product> Products { get; }

    public ProductCatalog(IEnumerable<Product> products) => Products = products.ToList();

    public int Count => Products.Count;

    /// The app's catalogue. Deterministic on purpose: the same 10,000 products
    /// every run, so a page boundary you find today is still there tomorrow.
    public static ProductCatalog Seeded(int count = 10_000) => new(Generate(count));

    private static IEnumerable<Product> Generate(int count)
    {
        string[] categories = ["tools", "toys", "books", "food", "garden"];
        string[] adjectives = ["Rustic", "Sleek", "Handmade", "Refined", "Ergonomic"];
        string[] nouns = ["Chair", "Lamp", "Table", "Mug", "Shelf"];

        for (int i = 1; i <= count; i++)
            yield return new Product(
                Id: i,
                Name: $"{adjectives[i % 5]} {nouns[(i / 5) % 5]} #{i:D5}",
                Category: categories[i % 5],
                Price: 1.99m + (i % 500),
                Stock: i % 97);
    }
}

// Filter, then sort, then slice — in that order, and the order matters.
//
// Slice first and you page through the unfiltered catalogue and then hide most
// of what you found: page 1 might show three products and page 2 none. Sort
// after slicing and you sort twenty arbitrary items rather than picking the top
// twenty of everything. FILTER -> SORT -> SLICE is the only sequence that means
// what a user expects "page 2 of cheap chairs" to mean.

public static class ProductQuery
{
    public static PagedResult<Product> Apply(IReadOnlyList<Product> products, PageRequest request)
        => Paginator.Slice(Sort(Filter(products, request.Search), request.Sort), request);

    /// Case-insensitive substring match over name and category. A null or blank
    /// term means "everything" — normalized to null by PageRequest, so there is
    /// exactly one "no search" value to check for.
    public static IReadOnlyList<Product> Filter(IReadOnlyList<Product> products, string? search)
    {
        if (string.IsNullOrWhiteSpace(search)) return products;

        return products
            .Where(p => p.Name.Contains(search, StringComparison.OrdinalIgnoreCase)
                     || p.Category.Contains(search, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }

    /// The whitelist IS this switch. There is no path from a client string to a
    /// property lookup — the worst an unknown field can do is fall to the `_`
    /// case, and Validate has already rejected it with a 400 before we get here.
    public static IReadOnlyList<Product> Sort(IReadOnlyList<Product> products, string sort)
    {
        var (field, descending) = PageRequest.ParseSort(sort);

        IOrderedEnumerable<Product> ordered = (field, descending) switch
        {
            ("name", false) => products.OrderBy(p => p.Name, StringComparer.Ordinal),
            ("name", true) => products.OrderByDescending(p => p.Name, StringComparer.Ordinal),
            ("price", false) => products.OrderBy(p => p.Price),
            ("price", true) => products.OrderByDescending(p => p.Price),
            ("stock", false) => products.OrderBy(p => p.Stock),
            ("stock", true) => products.OrderByDescending(p => p.Stock),
            (_, true) => products.OrderByDescending(p => p.Id),
            _ => products.OrderBy(p => p.Id),
        };

        // The tie-break is not a nicety — it is what makes pagination CORRECT.
        // Sorting by price alone leaves products with equal prices in an
        // unspecified order, and "unspecified" is free to differ between the
        // request for page 1 and the request for page 2. A product then appears
        // on both pages while another appears on neither. Adding `ThenBy(Id)`
        // makes the order TOTAL: every item has exactly one position, so the
        // pages tile the catalogue exactly once.
        return (descending ? ordered.ThenByDescending(p => p.Id) : ordered.ThenBy(p => p.Id))
            .ToList();
    }
}

if (args.Contains("test")) { Environment.Exit(Tests.Run()); }

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton(ProductCatalog.Seeded());
var app = builder.Build();

// ONE list endpoint. There is no "give me everything" route, because there is
// no request a client can send that makes shipping 10,000 rows a good idea.
//
// Look at the parameter list: `int? page`, `int? pageSize`. These are TYPED,
// and that is the whole junk-input defence. ASP.NET Core parses them for us
// and answers `?page=abc` with a 400 before this lambda ever runs — no
// int.Parse, no try/catch, no 500. Making the type do the validation is
// cheaper and more reliable than remembering to check (cs#05, cs#17).
app.MapGet("/products", (int? page, int? pageSize, string? sort, string? search,
                         ProductCatalog catalog) =>
{
    // Reject what has no obvious intent...
    var errors = PageRequest.Validate(sort);
    if (errors.Count > 0) return Results.BadRequest(new { errors });

    // ...clamp what does, then hand a fully-normalized request to pure code.
    var request = PageRequest.Normalize(page, pageSize, sort, search);
    return Results.Ok(ProductQuery.Apply(catalog.Products, request));
});

// Handy for the experiments in LEARN.md: how big the original's answer was.
app.MapGet("/products/count", (ProductCatalog catalog) =>
    Results.Ok(new { totalItems = catalog.Count, maxPageSize = PageRequest.MaxPageSize }));

app.Run("http://localhost:5034");

public static class Tests
{
    public static int Run()
    {
        Console.WriteLine("PageRequest.Normalize: clamp what has an obvious intent");
        Check.Equal(1, PageRequest.Normalize(null, null, null, null).Page, "no page means page 1");
        Check.Equal(1, PageRequest.Normalize(0, null, null, null).Page, "page 0 clamps up to 1");
        Check.Equal(1, PageRequest.Normalize(-5, null, null, null).Page, "a negative page clamps up to 1");
        Check.Equal(7, PageRequest.Normalize(7, null, null, null).Page, "a sensible page is left alone");

        Check.Equal(20, PageRequest.Normalize(null, null, null, null).PageSize, "the default page size is 20");
        Check.Equal(1, PageRequest.Normalize(null, 0, null, null).PageSize, "pageSize 0 clamps up to 1");
        Check.Equal(1, PageRequest.Normalize(null, -99, null, null).PageSize, "a negative pageSize clamps up to 1");
        Check.Equal(50, PageRequest.Normalize(null, 50, null, null).PageSize, "a sensible pageSize is left alone");
        Check.Equal(100, PageRequest.Normalize(null, 100_000, null, null).PageSize, "pageSize is CAPPED, not honoured");
        Check.Equal(PageRequest.MaxPageSize, PageRequest.Normalize(null, int.MaxValue, null, null).PageSize,
            "even int.MaxValue only gets you MaxPageSize");

        Check.Equal("id", PageRequest.Normalize(null, null, null, null).Sort, "the default sort is id");
        Check.Equal("id", PageRequest.Normalize(null, null, "   ", null).Sort, "a blank sort is the default sort");
        Check.Equal("price", PageRequest.Normalize(null, null, "  PRICE ", null).Sort, "sort is trimmed and lowercased");
        Check.Equal("-price", PageRequest.Normalize(null, null, "-Price", null).Sort, "the descending prefix survives");

        Check.Equal(null, PageRequest.Normalize(null, null, null, null).Search, "no search is null");
        Check.Equal(null, PageRequest.Normalize(null, null, null, "   ").Search, "a blank search is ALSO null, not \"   \"");
        Check.Equal("mug", PageRequest.Normalize(null, null, null, "  mug  ").Search, "search is trimmed");

        Console.WriteLine("PageRequest.Validate: reject what has no obvious intent");
        Check.Equal(0, PageRequest.Validate(null).Count, "no sort is valid");
        Check.Equal(0, PageRequest.Validate("price").Count, "a whitelisted field is valid");
        Check.Equal(0, PageRequest.Validate("-PRICE").Count, "case and direction don't change the field");
        Check.Equal(1, PageRequest.Validate("pirce").Count, "a typo is rejected, not guessed at");
        Check.True(PageRequest.Validate("pirce")[0].Contains("price"), "and the error lists what IS allowed");
        Check.Equal(1, PageRequest.Validate("costPrice").Count, "an internal-sounding name is rejected too");
        Check.Equal(1, PageRequest.Validate("-nope").Count, "descending junk is still junk");

        Console.WriteLine("PageRequest.ParseSort");
        Check.Equal("price", PageRequest.ParseSort("price").Field, "a bare field is the field");
        Check.Equal(false, PageRequest.ParseSort("price").Descending, "...ascending by default");
        Check.Equal("price", PageRequest.ParseSort("-price").Field, "the '-' is not part of the field name");
        Check.Equal(true, PageRequest.ParseSort("-price").Descending, "...and it means descending");

        Console.WriteLine("Paginator.Slice: the boundaries where off-by-ones live");
        var items = Enumerable.Range(1, 25).ToList();

        var p1 = Paginator.Slice(items, new PageRequest(1, 10, "id", null));
        Check.Equal(1, p1.Items[0], "PAGE 1 STARTS AT THE FIRST ITEM (the original's bug)");
        Check.Equal(10, p1.Items.Count, "a full page has pageSize items");
        Check.Equal(10, p1.Items[^1], "...and ends where you'd expect");
        Check.Equal(25, p1.TotalItems, "the envelope reports the real total");
        Check.Equal(3, p1.TotalPages, "25 items at 10 per page is 3 pages, not 2");

        var p2 = Paginator.Slice(items, new PageRequest(2, 10, "id", null));
        Check.Equal(11, p2.Items[0], "page 2 starts exactly where page 1 stopped");
        Check.Equal(20, p2.Items[^1], "no gap, no overlap");

        var p3 = Paginator.Slice(items, new PageRequest(3, 10, "id", null));
        Check.Equal(5, p3.Items.Count, "the LAST page is partial, and that's fine");
        Check.Equal(21, p3.Items[0], "it starts right after page 2");
        Check.Equal(25, p3.Items[^1], "and ends at the last item");

        var p4 = Paginator.Slice(items, new PageRequest(4, 10, "id", null));
        Check.Equal(0, p4.Items.Count, "a page past the end is EMPTY, not a crash");
        Check.Equal(25, p4.TotalItems, "...and still reports the real total");
        Check.Equal(3, p4.TotalPages, "...and the real page count");

        var huge = Paginator.Slice(items, new PageRequest(int.MaxValue, 20, "id", null));
        Check.Equal(0, huge.Items.Count,
            "page int.MaxValue is empty — the long cast stops the skip from overflowing NEGATIVE");

        var exact = Paginator.Slice(Enumerable.Range(1, 20).ToList(), new PageRequest(2, 10, "id", null));
        Check.Equal(10, exact.Items.Count, "when the last page is exactly full it is still a page");
        Check.Equal(2, exact.TotalPages, "20 items at 10 per page is exactly 2 pages");
        Check.Equal(0, Paginator.Slice(Enumerable.Range(1, 20).ToList(), new PageRequest(3, 10, "id", null)).Items.Count,
            "...and there is no page 3");

        var none = Paginator.Slice(new List<int>(), new PageRequest(1, 10, "id", null));
        Check.Equal(0, none.Items.Count, "an empty source gives an empty page");
        Check.Equal(0, none.TotalItems, "...zero items");
        Check.Equal(0, none.TotalPages, "...and ZERO pages, not one empty one");

        var one = Paginator.Slice(new List<int> { 42 }, new PageRequest(1, 10, "id", null));
        Check.Equal(1, one.TotalPages, "one item is one page");
        Check.Equal(42, one.Items[0], "...containing that item");

        Console.WriteLine("ProductQuery.Filter: case-insensitive, name or category");
        var catalog = Small();
        Check.Equal(5, ProductQuery.Filter(catalog.Products, null).Count, "no search means everything");
        Check.Equal(5, ProductQuery.Filter(catalog.Products, "   ").Count, "a blank search means everything");
        Check.Equal(2, ProductQuery.Filter(catalog.Products, "rustic").Count, "a name substring matches");
        Check.Equal(2, ProductQuery.Filter(catalog.Products, "RUSTIC").Count, "...case-insensitively");
        Check.Equal(2, ProductQuery.Filter(catalog.Products, "tools").Count, "a category matches too");
        Check.Equal(1, ProductQuery.Filter(catalog.Products, "mug").Count, "one match is one match");
        Check.Equal(0, ProductQuery.Filter(catalog.Products, "zzz").Count, "no matches is an empty list, not null");

        Console.WriteLine("ProductQuery.Sort: the whitelist, and the tie-break that makes paging correct");
        Check.Equal("1,2,3,4,5", Ids(ProductQuery.Sort(catalog.Products, "id")), "id ascending");
        Check.Equal("5,4,3,2,1", Ids(ProductQuery.Sort(catalog.Products, "-id")), "id descending");
        Check.Equal("4,2,1,3,5", Ids(ProductQuery.Sort(catalog.Products, "price")), "price ascending, ties broken by id");
        Check.Equal("5,3,1,2,4", Ids(ProductQuery.Sort(catalog.Products, "-price")), "price descending, ties broken by id");
        Check.Equal("4,1,3,2,5", Ids(ProductQuery.Sort(catalog.Products, "name")), "name ascending");
        Check.Equal("2,5,4,1,3", Ids(ProductQuery.Sort(catalog.Products, "stock")), "stock ascending");
        Check.Equal("1,2,3,4,5", Ids(ProductQuery.Sort(catalog.Products, "pirce")),
            "an unknown field falls back to id — it can never reach a property by name");

        Console.WriteLine("ProductQuery.Apply: filter, then sort, then slice");
        var filtered = ProductQuery.Apply(catalog.Products, PageRequest.Normalize(1, 1, "id", "rustic"));
        Check.Equal(2, filtered.TotalItems, "totals count the FILTERED set, not the catalogue");
        Check.Equal(2, filtered.TotalPages, "2 matches at 1 per page is 2 pages");
        Check.Equal(1, filtered.Items.Count, "the page holds one item");
        Check.Equal(1, filtered.Items[0].Id, "the first match");

        var filteredPage2 = ProductQuery.Apply(catalog.Products, PageRequest.Normalize(2, 1, "id", "rustic"));
        Check.Equal(3, filteredPage2.Items[0].Id, "page 2 of the filtered set is the second match");

        var noMatches = ProductQuery.Apply(catalog.Products, PageRequest.Normalize(1, 10, "id", "zzz"));
        Check.Equal(0, noMatches.TotalItems, "a search with no hits totals zero");
        Check.Equal(0, noMatches.TotalPages, "...and has zero pages");

        // Walk every page and prove the pages TILE the result set: every
        // product exactly once, none twice, none missing. This is the property
        // an unstable sort quietly breaks.
        var seen = new List<int>();
        var pages = ProductQuery.Apply(catalog.Products, PageRequest.Normalize(1, 2, "price", null)).TotalPages;
        for (int p = 1; p <= pages; p++)
            seen.AddRange(ProductQuery.Apply(catalog.Products, PageRequest.Normalize(p, 2, "price", null))
                .Items.Select(x => x.Id));
        Check.Equal(3, pages, "5 products at 2 per page is 3 pages");
        Check.Equal(5, seen.Count, "walking every page yields every product...");
        Check.Equal(5, seen.Distinct().Count(), "...exactly once (a total order makes pages tile)");

        Console.WriteLine("The real catalogue: 10,000 products, 20 at a time");
        var big = ProductCatalog.Seeded();
        Check.Equal(10_000, big.Count, "the app seeds 10,000 products");

        var first = ProductQuery.Apply(big.Products, PageRequest.Normalize(null, null, null, null));
        Check.Equal(20, first.Items.Count, "a bare GET returns 20 items, not 10,000");
        Check.Equal(10_000, first.TotalItems, "...while still saying how many exist");
        Check.Equal(500, first.TotalPages, "10,000 / 20 = 500 pages");
        Check.Equal(1, first.Items[0].Id, "and it starts at the first product");

        var last = ProductQuery.Apply(big.Products, PageRequest.Normalize(500, null, null, null));
        Check.Equal(20, last.Items.Count, "the last page is full");
        Check.Equal(10_000, last.Items[^1].Id, "...and ends at the last product");
        Check.Equal(0, ProductQuery.Apply(big.Products, PageRequest.Normalize(501, null, null, null)).Items.Count,
            "page 501 is empty, not a 500");

        var capped = ProductQuery.Apply(big.Products, PageRequest.Normalize(1, 999_999, null, null));
        Check.Equal(100, capped.Items.Count, "?pageSize=999999 gets you 100 items — the cap is the defence");

        return Check.Summary();
    }

    private static string Ids(IEnumerable<Product> products) => string.Join(",", products.Select(p => p.Id));

    // Five products chosen so that every interesting case has a hand-checkable
    // answer: a price tie (1 and 3), two names sharing a prefix, a zero stock.
    private static ProductCatalog Small() => new(
    [
        new Product(1, "Rustic Chair", "tools", 10.00m, 5),
        new Product(2, "Sleek Lamp", "toys", 5.00m, 0),
        new Product(3, "Rustic Table", "tools", 10.00m, 9),
        new Product(4, "Handmade Mug", "books", 2.50m, 3),
        new Product(5, "Sleek Shelf", "garden", 99.00m, 1),
    ]);
}
